import numpy as np
from pynwb import NWBHDF5IO
p=sorted(Path('/app/data').glob('*.nwb'))[0]
with NWBHDF5IO(str(p),'r',load_namespaces=True) as io:
 n=io.read()
 for cname,container in n.acquisition.items():
  print('\nCONTAINER',cname,type(container).__name__,getattr(container,'description',None))
  members=getattr(container,'time_series',{})
  for name,ts in members.items():
   data=ts.data; shape=getattr(data,'shape',None)
   print(' ',name,type(ts).__name__,'shape',shape,'unit',getattr(ts,'unit',None),'desc',getattr(ts,'description',None))
   print('   timestamps shape',getattr(getattr(ts,'timestamps',None),'shape',None),'starting_time',getattr(ts,'starting_time',None),'rate',getattr(ts,'rate',None))
   try:
    x=np.asarray(data[:min(8,shape[0])]); print('   data head',x)
   except Exception as e: print('   data head error',e)
   try:
    tt=np.asarray(ts.timestamps[:min(8,len(ts.timestamps))]); print('   time head',tt)
   except Exception: pass
 print('\nTRIAL VALUE COUNTS')
 df=n.trials.to_dataframe()
 for c in df.columns:
  if c not in ('start_time','stop_time'):
   vals=df[c]
   try: print(c,vals.value_counts(dropna=False).head(15).to_dict())
   except Exception as e: print(c,'error',e)
 print('\nUNIT QC COUNTS')
